INSERT INTO INVENTAIRE
(ID, DATY, DESIGNATION, IDMAGASIN, ETAT, REMARQUE, IDCATEGORIE, HEURE)
SELECT
    'IVTAG00'||GETSEQINVENTAIRE(),
    TIMESTAMP '2026-07-28 00:00:00.000000',
    'Inventaire chaussure',
    m.id,
    11,
    'Inventaire chaussure',
    NULL,
    '12:00:00'
FROM magasin2 m;


INSERT INTO INVENTAIREFILLE
(ID, IDINVENTAIRE, IDPRODUIT, EXPLICATION, IDJAUGE, QUANTITETHEORIQUE, QUANTITE, MVTSRC, PU, IDFOURNISSEUR, DATY)
SELECT
    'IVTAGFI00'||GETSEQINVENTAIREFILLE(),
    i.id,
    ing.id,
    ing.libelle,
    NULL,
    0,
    0,
    NULL,
    ing.pu,
    NULL,
    NULL
FROM INVENTAIRE i
CROSS JOIN AS_INGREDIENTS ing
WHERE i.ID LIKE 'IVTAG00%'
AND ing.id LIKE 'INGAGR%';

INSERT INTO MVTSTOCK
(ID, DESIGNATION, IDMAGASIN, IDVENTE, IDTRANSFERT, IDTYPEMVSTOCK, DATY, ETAT, IDPOINT, IDOBJET, FABPRECEDENT, IDCATEGORIESTOCK, HEURE)
SELECT
    'MVTSTAG00'||GETSEQMVTSTOCK(),
    'Mouvement de stock inventaire 0',
    m.id,
    NULL,
    NULL,
    'TPMVST000001',
    TIMESTAMP '2026-07-28 00:00:00.000000',
    11,
    m.idpoint,
    NULL,
    NULL,
    'CTGST000001',
    NULL
FROM magasin2 m;

INSERT INTO MVTSTOCKFILLE
(ID, IDMVTSTOCK, IDPRODUIT, IDVENTEDETAIL, IDTRANSFERTDETAIL, MVTSRC, DESIGNATION, ENTREE, SORTIE, PU, RESTE, IDINVENTAIREFILLE, DATEINVENTAIRE, QTEINVENTAIRE)
SELECT
    'MVTSAGFI00'||GETSEQMVTSTOCKFILLE(),
    m.id,
    ifille.idproduit,
    NULL,
    NULL,
    NULL,
    ifille.explication,
    0,
    0,
    ifille.pu,
    0,
    ifille.id,
    NULL,
    0
FROM MVTSTOCK m
JOIN INVENTAIRE i 
    ON i.idmagasin = m.idmagasin
JOIN INVENTAIREFILLE ifille 
    ON ifille.idinventaire = i.id
WHERE m.id LIKE 'MVTSTAG%'
AND i.ID LIKE 'IVTAG00%';

-- 1. Inventaire mère (une ligne par magasin)
INSERT INTO INVENTAIRE
(ID, DATY, DESIGNATION, IDMAGASIN, ETAT, REMARQUE, IDCATEGORIE, HEURE)
SELECT
    'IVTAG00'||GETSEQINVENTAIRE(),
    TIMESTAMP '2026-07-29 00:00:00.000000',
    'Inventaire chaussure',
    m.id,
    1,
    'Inventaire chaussure',
    NULL,
    '12:00:00'
FROM MAGASIN2 m
WHERE m.id IN ('PHARM002', 'ETAB049');



-- 2. Inventaire fille (tous les ingrédients INGAGR%, quantité 300)
INSERT INTO INVENTAIREFILLE
(ID, IDINVENTAIRE, IDPRODUIT, EXPLICATION, IDJAUGE, QUANTITETHEORIQUE, QUANTITE, MVTSRC, PU, IDFOURNISSEUR, DATY)
SELECT
    'IVTAGFI00'||GETSEQINVENTAIREFILLE(),
    i.id,
    ing.id,
    ing.libelle,
    NULL,
    0,
    300,
    NULL,
    ing.pu,
    NULL,
    NULL
FROM INVENTAIRE i
JOIN MAGASIN2 m ON m.id = i.idmagasin
CROSS JOIN AS_INGREDIENTS ing
WHERE m.id IN ('PHARM002', 'ETAB049')
AND ing.id LIKE 'INGAGR%'
AND i.DATY = TIMESTAMP '2026-07-29 00:00:00.000000';

